-- 保存截图
function UI_Share_Component:OnSavePicture()
    PopUpNoticeUI.RemoveAllNotice()

    -- timer里无法截图，需要底层代码处理
    self.sSharePath = ScreenshotMaker.MakePicture(true)
    self:AddTimer(0, function()
    --self:AddTimer(0.2, function()
        --self.sSharePath = ScreenshotMaker.MakePicture(true)
        while true do
            coroutine.yield(0.1)
            self:SavePictureHandler()
        end
    end)
end

function UI_Share_Component:SavePictureHandler()
    log("[edward][share_component] sSharePath" .. self.sSharePath)
    if ScreenshotMaker.HasCaptured(self.sSharePath) then
        self:RemoveAllTimer()

        local vector;
        if self.UIRoot.GetContentVector4 then
            vector = self.UIRoot:GetContentVector4();
        end
        ScreenshotMaker.ReMakePicture(self.sSharePath, vector)

        if self.eShareType == E_ShareType.None then
            ScreenshotMaker.SaveToPhotosAlbumEx(self.sSharePath)
        elseif self.eShareType == E_ShareType.Facebook then
            self:OnFacebook()
        elseif self.eShareType == E_ShareType.Twitter then
            self:OnTwitter()
        elseif self.eShareType == E_ShareType.WeChat then
            self:OnWXZone()
        elseif self.eShareType == E_ShareType.VK then
            self:OnVK()
        elseif self.eShareType == E_ShareType.Line then
            self:OnLine()
        elseif self.eShareType == E_ShareType.QQ then
            self:OnQQByiTOP()
        end
    end
end

-- slua暂时没有导出FVector4结构体，暂时弃用此方法，改用BP实现
function UI_Share_Component:GetContentVector4(widget)
    local geometry = widget:GetCachedGeometry()
    local SlateBlueprintLibrary = import("SlateBlueprintLibrary")
    local position = SlateBlueprintLibrary.LocalToAbsolute(geometry, FVector2D(0, 0))
    local size = SlateBlueprintLibrary.GetAbsoluteSize(geometry)
    return FVector4(position.X, position.Y, size.X, size.Y)
end

function UI_Share_Component:OnSaveLocal()
    self.eShareType = E_ShareType.None
    self:OnSavePicture()
end

