-- 分享facebook
function UI_Share_Component:OnFacebook()
    if Client.IsInstallQQ(NetInterface) == false then
        --你还没有安装Facebook，无法使用此功能
        DataMgr.ShowNoticeByID(4005)
        return
    end

    ShareMgr:shareQQWithPhoto(MEDIA_TAG_SHARE_CHIJI, "", self.sSharePath, ShareType.Moment)
    ClientSendBAReport(BP_BA_SHARE_QQSPACE, 0)
    ShareMgr.ShareSuccReq(self.eShareReqType, BP_BA_SHARE_FACEBOOK)
end

-- 分享twitter
function UI_Share_Component:OnTwitter()
    if Client.IsInstallTwitter(NetInterface) == false then
        --你还没有安装twitter，无法使用此功能
        --DataMgr.ShowNoticeByID(4062);
        --return;
    end

    log("[edward][share_component] OnTwitter " .. self.sSharePath);
    ShareMgr:shareWithPhotoByChannel(MEDIA_TAG_SHARE_CHIJI, self.sSharePath, "", "", BP_ENUM_PLAYFORM_TWITTER)
    ClientSendBAReport(BP_BA_SHARE_TW_COUNT, 0)
    ShareMgr.ShareSuccReq(self.eShareReqType, BP_BA_SHARE_TWITTER)
end

